Given two distinct words s and e, and a list of unique words words[], where all words have the same length, find the length of the shortest transformation sequences from start to end. A valid transformation sequence must satisfy the following conditions:Only one character can be changed in each transformation.Every transformed word must exist in words[], including e.All words consist only of lowercase English letters.s may or may not be present in words[].Return the length of the shortest transformation sequence from s to e. If no such sequence exists, return 0.Examples:Input: words[] = ["des", "der", "dfr", "dgt", "dfs"], start = "der", end = "dfs"Output: 3Explanation: The length of the smallest transformation sequence from "der" to "dfs" is 3 i.e "der" -> "dfr" -> "dfs".Input: words[] = ["geek", "gefk"], start = "gedk", end = "geek"Output: 2Explanation: The length of the smallest transformation sequence from "gedk" to "geek" is 2 i.e "gedk" -> "geek".Input: words[] = ["poon", "plee", "same", "poie", "plea", "plie", "poin"], start = "toon", end = "plea"Output: 7 Explanation: The length of the smallest transformation sequence from "toon" to "plea" is 7 i.e toon -> poon -> poin -> poie -> plie -> plee -> plea.Try It YourselfTable of Content[Naive Approach] Backtracking Over All Possible Sequences - O(n!) Time and O(n) Space[Expected Approach] BFS with Hash Set - O(n m) Time and O(n) Space[Naive Approach] Backtracking Over All Possible Sequences - O(n!) Time and O(n) SpaceThe idea is to recursively try every possible transformation sequence starting from start. From the current word, move to every unvisited word that differs by exactly one character and keep track of the minimum sequence length that reaches end.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Recursive function to find the shortest transformation chain
int minWordTransform(string start, string target, map<string, int> &mp)
{

    // If start word is the same as target, no transformation is needed
    if (start == target)
        return 1;

    int mini = INT_MAX;

    // Mark current word as visited
    mp[start] = 1;

    // Try changing each character of the word
    for (int i = 0; i < start.size(); i++)
    {
        char originalChar = start[i];

        // Try all possible lowercase letters at position i
        for (char ch = 'a'; ch <= 'z'; ch++)
        {
            start[i] = ch;

            // If the new word exists in dictionary and is not visited
            if (mp.find(start) != mp.end() && mp[start] == 0)
            {

                // Recursive call for next transformation
                int curr = minWordTransform(start, target, mp);

                if (curr != INT_MAX)
                    mini = min(mini, 1 + curr);
            }
        }

        // Restore original character before moving to the next position
        start[i] = originalChar;
    }

    // Mark current word as unvisited (backtracking)
    mp[start] = 0;

    return mini;
}

int wordLadder(vector<string> &words, string &s, string &e)
{

    // Initialize all words from the dictionary as unvisited
    map<string, int> mp;

    for (auto word : words)
        mp[word] = 0;

    int result = minWordTransform(s, e, mp);

    if (result == INT_MAX)
        result = 0;

    return result;
}

int main()
{

    vector<string> words = {"poon", "plee", "same", "poie", "plea", "plie", "poin"};

    string s = "toon";
    string e = "plea";

    cout << wordLadder(words, s, e);

    return 0;
}


